<?php
declare(strict_types=1);
require_once __DIR__ . '/../src/actions.php';
require_once __DIR__ . '/../src/progress.php';

$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';
if($path!=='/'&&str_ends_with($path,'/')&&$path!=='/public/')$path=rtrim($path,'/');
if($path==='/api/health'){header('Content-Type: application/json');try{db()->query('SELECT 1');echo '{"ok":true}';}catch(Throwable $e){http_response_code(503);echo '{"ok":false}';}exit;}
if($path==='/branding/logo'){
    $identity=site_branding();$mime=$identity['logo_mime']??'';$data=$identity['logo_data']??'';
    if(!in_array($mime,['image/png','image/jpeg','image/webp'],true)||!is_string($data)||$data===''){http_response_code(404);exit;}
    $bytes=base64_decode($data,true);if($bytes===false){http_response_code(404);exit;}
    header('Content-Type: '.$mime);header('Content-Length: '.strlen($bytes));header('X-Content-Type-Options: nosniff');header('Cache-Control: public, max-age=0, must-revalidate');echo $bytes;exit;
}
$user=current_user();
if($_SERVER['REQUEST_METHOD']==='POST')run_action($user);

function qall(string $sql,array $params=[]): array {$q=db()->prepare($sql);$q->execute($params);return $q->fetchAll();}
function qone(string $sql,array $params=[]): ?array {$q=db()->prepare($sql);$q->execute($params);$r=$q->fetch();return $r?:null;}
function qcount(string $sql,array $params=[]): int {$q=db()->prepare($sql);$q->execute($params);return (int)$q->fetchColumn();}
function badge(string $status): string {return '<span class="badge '.h($status).'">'.h(status_label($status)).'</span>';}
function hidden_csrf(): string {return csrf_field();}
function action_open(string $action,string $extra=''): string {return '<form method="post" action="'.h($extra!==''?$extra:'/'). '"'.(in_array($action,['motion_create','motion_resubmit','branding_update'],true)?' enctype="multipart/form-data"':'').' class="'.($extra==='download'?'':'').'">'.hidden_csrf().'<input type="hidden" name="action" value="'.h($action).'">';}
function icon_mark(): string {return '<svg class="brand-mark" viewBox="0 0 48 48" role="img" aria-label="e-Bunge chamber mark"><path d="M7 39V24C7 13.5 14.6 6 24 6s17 7.5 17 18v15" fill="none" stroke="currentColor" stroke-width="2.4"/><path d="M13 39h22M15 23h18M17 29h14M19 35h10" fill="none" stroke="#c9a667" stroke-width="2.4" stroke-linecap="round"/><circle cx="24" cy="17" r="2" fill="#c9a667"/></svg>';}
function brand(): string {$settings=site_branding();$mark=!empty($settings['logo_data'])&&in_array($settings['logo_mime']??'', ['image/png','image/jpeg','image/webp'],true)?'<img class="brand-mark brand-mark-image" src="/branding/logo" alt="">':icon_mark();return '<a class="brand" href="/">'.$mark.'<span class="brand-name">e-Bunge<small>'.h($settings['motto']??'County Assembly').'</small></span></a>';}
function render_start(string $title,?array $user=null): void {
    global $path;
    $f=take_flash();$branding=site_branding();$favicon=!empty($branding['logo_data'])?'/branding/logo':'/assets/logo.svg';
    echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>'.h($title).' · e-Bunge</title><meta name="description" content="Digital County Assembly motion and proceedings platform"><link rel="icon" href="'.h($favicon).'"'.(empty($branding['logo_data'])?' type="image/svg+xml"':'').'><link rel="stylesheet" href="/assets/style.css"><script defer src="/assets/app.js"></script></head><body><a class="skip-link" href="#main">Skip to main content</a>';
    if($user){
        $r=$user['role'];$items=[['/dashboard','⌂','Overview'],['/motions','▤','Motions'],['/sittings','◷','Sittings'],['/attendance','✓','Attendance'],['/voting','◉','Voting Center'],['/committees','▥','Committees'],['/petitions','≋','Petitions'],['/reports','⇩','Reports'],['/activity','↻','Activity']];
        if($r==='speaker')$items[]=['/settings/branding','◈','Assembly identity'];
        echo '<div class="app-layout"><aside class="sidebar" id="sidebar">'.brand().'<div class="nav-label">Workspace</div><nav class="side-nav" aria-label="Main navigation">';
        foreach($items as [$href,$icon,$label]){$active=$path===$href||str_starts_with($path,rtrim($href,'/').'/');echo '<a class="'.($active?'active':'').'" href="'.h($href).'"><span class="nav-icon" aria-hidden="true">'.$icon.'</span>'.h($label).'</a>';}
        echo '</nav><div class="side-bottom"><div class="account-mini"><strong>'.h($user['username']).'</strong>'.h(role_name($r)).'</div>'.action_open('logout').'<button class="signout" type="submit">↗ &nbsp;Sign out</button></form></div></aside><div class="main-area"><header class="topbar"><div class="mobile-menu"><button class="menu-toggle" data-menu-toggle aria-expanded="false" aria-label="Open navigation">☰</button><p>Legislative workspace</p></div><div class="user-pill"><span>'.h(role_name($r)).'</span><div class="avatar" aria-hidden="true">'.h(mb_strtoupper(mb_substr($user['username'],0,1))).'</div></div></header><main class="main-content" id="main">';
    }else{
        echo '<header class="public-header"><div class="container header-row">'.brand().'<nav class="nav-actions" aria-label="Account navigation"><a class="btn btn-quiet" href="/public">Public portal</a><a class="btn btn-secondary" href="/signin">Sign in</a><a class="btn btn-primary" href="/register">Create account</a></nav></div></header><main id="main">';
    }
    if($f)echo '<div class="alert '.h($f['kind']).'" role="status">'.h($f['message']).'</div>';
}
function render_end(?array $user=null): void {if($user)echo '</main></div></div>';else echo '</main>';echo '</body></html>';}
function page_heading(string $eyebrow,string $title,string $description='',string $actions=''): void {echo '<div class="page-heading"><div><div class="eyebrow">'.h($eyebrow).'</div><h1>'.h($title).'</h1>'.($description!==''?'<p>'.h($description).'</p>':'').'</div>'.($actions!==''?'<div class="heading-actions">'.$actions.'</div>':'').'</div>';}
function btn_link(string $href,string $label,string $kind='primary'): string {return '<a class="btn btn-'.$kind.'" href="'.h($href).'">'.h($label).'</a>';}
function field(string $label,string $name,string $type='text',string $value='',string $placeholder='',bool $required=true,string $attrs=''): string {return '<div class="field"><label for="'.h($name).'">'.h($label).'</label><input id="'.h($name).'" name="'.h($name).'" type="'.h($type).'" value="'.h($value).'" placeholder="'.h($placeholder).'" '.($required?'required':'').' '.$attrs.'></div>';}
function textarea_field(string $label,string $name,string $placeholder='',bool $required=true,string $value=''): string {return '<div class="field"><label for="'.h($name).'">'.h($label).'</label><textarea id="'.h($name).'" name="'.h($name).'" placeholder="'.h($placeholder).'" '.($required?'required':'').'>'.h($value).'</textarea></div>';}
function post_button(string $action,string $label,string $kind='primary',array $hidden=[]): string {$s=action_open($action);foreach($hidden as $k=>$v)$s.='<input type="hidden" name="'.h($k).'" value="'.h($v).'">';return $s.'<button class="btn btn-'.$kind.' btn-small" type="submit">'.h($label).'</button></form>';}
function empty_state(string $title,string $copy): string {return '<div class="empty"><strong>'.h($title).'</strong>'.h($copy).'</div>';}
function status_select(string $label,string $name,array $values,string $selected=''): string {$html='<div class="field"><label for="'.h($name).'">'.h($label).'</label><select id="'.h($name).'" name="'.h($name).'" required>';foreach($values as $key=>$value)$html.='<option value="'.h($key).'" '.($selected===$key?'selected':'').'>'.h($value).'</option>';$html.='</select></div>';return $html;}

if($path==='/branding/logo'){
    $settings=site_branding();$mime=$settings['logo_mime']??'';$bytes=is_string($settings['logo_data']??null)?base64_decode($settings['logo_data'],true):false;
    if(!in_array($mime,['image/png','image/jpeg','image/webp'],true)||$bytes===false){http_response_code(404);exit;}
    header('Content-Type: '.$mime);header('X-Content-Type-Options: nosniff');header('Cache-Control: no-cache, must-revalidate');header('Content-Length: '.strlen($bytes));echo $bytes;exit;
}
if($path==='/favicon.ico'){http_response_code(204);exit;}
if(preg_match('#^/download/motion/(\d+)$#',$path,$m)){
    $u=require_login();$doc=qone('SELECT d.*,m.sponsor_id FROM documents d JOIN motions m ON m.id=d.motion_id WHERE d.id=?',[(int)$m[1]]);
    if(!$doc||($u['role']==='mca'&&(int)$doc['sponsor_id']!==(int)$u['id'])){http_response_code(404);exit('Document not found.');}
    $file=upload_directory().'/'.$doc['stored_name'];if(!is_file($file)){http_response_code(404);exit('Document not found.');}
    header('Content-Type: application/octet-stream');header('X-Content-Type-Options: nosniff');header('Content-Length: '.filesize($file));header("Content-Disposition: attachment; filename*=UTF-8''".rawurlencode($doc['original_name']));readfile($file);exit;
}
if(preg_match('#^/download/report/(\d+)$#',$path,$m)){
    $u=require_login();$report=qone('SELECT * FROM reports WHERE id=? AND status="approved"',[(int)$m[1]]);if(!$report){http_response_code(404);exit('Report not found.');}
    $type=$report['report_type'];$rows=[];$filename='ebunge-'.$type.'-'.date('Ymd').'.csv';
    if($type==='motions'){$sql=$u['role']==='mca'?'SELECT reference,title,category,status,created_at FROM motions WHERE sponsor_id=? ORDER BY created_at DESC':'SELECT reference,title,category,status,created_at FROM motions ORDER BY created_at DESC';$rows=qall($sql,$u['role']==='mca'?[$u['id']]:[]);}
    elseif($type==='petitions'){$rows=$u['role']==='mca'?qall('SELECT reference,title,status,created_at FROM petitions WHERE user_id=? ORDER BY created_at DESC',[$u['id']]):qall('SELECT reference,title,status,source,created_at FROM petitions ORDER BY created_at DESC');}
    elseif($type==='attendance'){$rows=$u['role']==='mca'?qall('SELECT s.title,s.sitting_date,a.attendance_status,a.approved FROM attendance a JOIN sittings s ON s.id=a.sitting_id WHERE a.user_id=? ORDER BY s.sitting_date DESC',[$u['id']]):qall('SELECT s.title,s.sitting_date,u.username,a.attendance_status,a.approved FROM attendance a JOIN sittings s ON s.id=a.sitting_id JOIN users u ON u.id=a.user_id ORDER BY s.sitting_date DESC');}
    elseif($type==='voting'){$rows=$u['role']==='mca'?qall('SELECT v.choice,v.cast_at,s.title FROM votes v JOIN vote_subjects s ON s.id=v.subject_id WHERE v.user_id=? AND s.status="result_approved" ORDER BY v.cast_at DESC',[$u['id']]):qall('SELECT s.title,s.status,SUM(v.choice="yes") AS yes,SUM(v.choice="no") AS no,SUM(v.choice="abstain") AS abstain FROM vote_subjects s LEFT JOIN votes v ON v.subject_id=s.id WHERE s.status="result_approved" GROUP BY s.id');}
    elseif($type==='committees'){$rows=$u['role']==='mca'?qall('SELECT c.name,c.status FROM committees c JOIN committee_members cm ON cm.committee_id=c.id WHERE cm.user_id=? AND c.status="approved"',[$u['id']]):qall('SELECT c.name,c.status,COUNT(cm.user_id) AS members FROM committees c LEFT JOIN committee_members cm ON cm.committee_id=c.id WHERE c.status="approved" GROUP BY c.id');}
    header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.$filename.'"');header('X-Content-Type-Options: nosniff');$out=fopen('php://output','w');fputcsv($out,['e-Bunge — '.$report['title']]);if($rows){fputcsv($out,array_keys($rows[0]));foreach($rows as $row)fputcsv($out,array_values($row));}else fputcsv($out,['No matching records']);fclose($out);audit((int)$u['id'],'downloaded','report',(int)$report['id'],'Downloaded '.$report['title']);exit;
}

