    $rows=qall('SELECT reference,title,category,created_at FROM motions WHERE status="approved_for_tabling" ORDER BY created_at DESC LIMIT 30');if($rows){echo '<div class="table-wrap"><table class="data-table"><thead><tr><th>Reference</th><th>Motion</th><th>Category</th><th>Approved record</th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td class="record-ref">'.h($r['reference']).'</td><td><strong>'.h($r['title']).'</strong></td><td>'.h($r['category']).'</td><td>'.h(substr($r['created_at'],0,10)).'</td></tr>';echo '</tbody></table></div>';}else echo empty_state('No approved motions to display','Approved motions will appear here when they are released for public viewing.');echo '</section><section class="card" style="margin-top:16px"><div class="card-header"><div><h2>Approved sittings</h2><p>Past and upcoming house sessions approved by the Office of the Speaker.</p></div></div>'; $sessions=qall('SELECT title,sitting_type,sitting_date,start_time,venue FROM sittings WHERE status="approved" ORDER BY sitting_date DESC,start_time DESC LIMIT 20');if($sessions){echo '<div class="table-wrap"><table class="data-table"><thead><tr><th>Session</th><th>Date and time</th><th>Venue</th></tr></thead><tbody>';foreach($sessions as $session)echo '<tr><td><strong>'.h($session['title']).'</strong><br><small class="muted">'.h($session['sitting_type']).'</small></td><td>'.h($session['sitting_date']).' · '.h($session['start_time']).'</td><td>'.h($session['venue']).'</td></tr>';echo '</tbody></table></div>';}else echo empty_state('No approved sittings to display','Speaker-approved house sessions will appear here.');echo '</section><section class="card" style="margin-top:16px"><div class="card-header"><div><h2>Approved petitions</h2><p>Petitions approved for public viewing by the Office of the Speaker.</p></div></div>';$rows=qall('SELECT reference,title,body,created_at FROM petitions WHERE source="public" AND public_status=1 AND status="approved" ORDER BY created_at DESC LIMIT 30');if