function speaker_decision_tasks(int $speakerId): array {
    $incoming=qall("SELECT 'Motion' AS kind,reference AS ref,title,status,updated_at AS happened,'/motions' AS href,id FROM motions WHERE status='speaker_review'
      UNION ALL SELECT 'Petition',reference,title,status,updated_at,'/petitions',id FROM petitions WHERE status='speaker_review'
      UNION ALL SELECT 'Sitting','SIT · '||id,title,status,updated_at,'/sittings',id FROM sittings WHERE status='speaker_review'
      UNION ALL SELECT 'Attendance','ATT · '||id,title,'speaker_review',updated_at,'/attendance',id FROM sittings WHERE attendance_status='speaker_review'
      UNION ALL SELECT 'Voting subject','VOTE · '||id,title,status,updated_at,'/voting',id FROM vote_subjects WHERE status IN ('speaker_review','result_pending')
      UNION ALL SELECT 'Committee','COM · '||id,name,status,updated_at,'/committees',id FROM committees WHERE status='speaker_review'
      UNION ALL SELECT 'Committee meeting','MTG · '||id,title,status,created_at,'/committees',id FROM committee_meetings WHERE status='speaker_review'
      UNION ALL SELECT 'Report','RPT · '||id,title,status,created_at,'/reports',id FROM reports WHERE status='speaker_review'
      ORDER BY happened DESC LIMIT 30");
    $waiting=qall("SELECT 'Motion' AS kind,reference AS ref,title,status,updated_at AS happened,'/motions' AS href,id FROM motions WHERE status='hansard_review'
      UNION ALL SELECT 'Petition',reference,title,status,updated_at,'/petitions',id FROM petitions WHERE status='hansard_review'
      UNION ALL SELECT 'MCA voting','VOTE · '||id,title,status,updated_at,'/voting',id FROM vote_subjects WHERE status='open'
      UNION ALL SELECT 'Hansard result review','VOTE · '||id,title,status,updated_at,'/voting',id FROM vote_subjects WHERE status='hansard_result_review'
      UNION ALL SELECT 'Motion correction','MOT · '||id,title,status,updated_at,'/motions',id FROM motions WHERE status='returned_for_correction'
      UNION ALL SELECT 'Petition correction',reference,title,status,updated_at,'/petitions',id FROM petitions WHERE status='returned_for_correction'
      UNION ALL SELECT 'Sitting correction','SIT · '||id,title,status,updated_at,'/sittings',id FROM sittings WHERE status='returned_for_correction'
      UNION ALL SELECT 'Voting correction','VOTE · '||id,title,status,updated_at,'/voting',id FROM vote_subjects WHERE status IN ('returned_for_correction','result_returned')
      UNION ALL SELECT 'Committee correction','COM · '||id,name,status,updated_at,'/committees',id FROM committees WHERE status='returned_for_correction'
      ORDER BY happened DESC LIMIT 30");
    $done=qall("SELECT action,record_type,record_id,summary,created_at AS happened FROM audit_logs WHERE user_id=? AND action IN ('approved','returned','decision','status_change','attendance_approved') AND record_type IN ('motion','petition','sitting','vote_subject','committee','committee_meeting','report') ORDER BY id DESC LIMIT 12",[$speakerId]);
    return ['incoming'=>$incoming,'waiting'=>$waiting,'done'=>$done];
}
function render_speaker_task_group(string $title,string $description,array $tasks,string $empty,bool $incoming=false): string {
    $html='<section class="decision-lane"><div class="decision-lane-head"><div><h2>'.h($title).'</h2><p>'.h($description).'</p></div><span class="decision-count">'.count($tasks).'</span></div>';
    if(!$tasks)return $html.'<p class="decision-empty">'.h($empty).'</p></section>';
    foreach($tasks as $task){
        $ref=(string)($task['ref']??strtoupper(substr((string)($task['record_type']??''),0,3)).' · '.(string)($task['record_id']??''));
        $type=(string)($task['kind']??status_label((string)($task['record_type']??'record')));
        $href=(string)($task['href']??match($task['record_type']??''){ 'motion'=>'/motions','petition'=>'/petitions','sitting'=>'/sittings','vote_subject'=>'/voting','committee'=>'/committees','committee_meeting'=>'/committees','report'=>'/reports',default=>'/activity'});
        $label=(string)($task['title']??$task['summary']??'Workflow update');
        $html.='<article class="decision-task"><div><span class="record-ref">'.h($type).' · '.h($ref).'</span><h3>'.h($label).'</h3><small>'.h($task['happened']??'').'</small></div><div class="decision-task-actions">';
        if(isset($task['status']))$html.=badge((string)$task['status']);
        $html.='<a class="btn btn-secondary btn-small" href="'.h($href).'">'.(($type==='Attendance'&&$incoming)?'Review attendance':'Open record').'</a>';
        if($incoming&&$type==='Attendance')$html.=post_button('attendance_approve','Approve attendance','primary',['id'=>$task['id']]);
        $html.='</div></article>';
    }
    return $html.'</section>';
}

