        echo '<div class="card-header"><div><h2>Reports awaiting Speaker approval</h2><p>'.($r==='speaker'?'Review submitted reports before making them available.':'These reports are awaiting a Speaker decision.').'</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Report</th><th>Type</th><th>Prepared by</th><th>Status</th><th>Action</th></tr></thead><tbody>';
        foreach($pending as $x)echo '<tr><td>'.h($x['title']).'</td><td>'.h(ucfirst($x['report_type'])).'</td><td>'.h($x['username']).'</td><td>'.badge($x['status']).'</td><td>'.($r==='speaker'?post_button('report_approve','Approve','primary',['id'=>$x['id']]):'Awaiting Speaker approval').'</td></tr>';
        echo '</tbody></table></div><div class="separator"></div>';
    }
    echo '<div class="card-header"><div><h2>Approved reports</h2><p>CSV downloads are limited to records available to your account.</p></div></div>';
    if(!$rows)echo empty_state('No approved reports','Reports become available here after the required approval.');
    else{echo '<div class="table-wrap"><table class="data-table"><thead><tr><th>Report</th><th>Type</th><th>Prepared by</th><th>Created</th><th>Download</th></tr></thead><tbody>';foreach($rows as $x)echo '<tr><td><strong>'.h($x['title']).'</strong></td><td>'.h(ucfirst($x['report_type'])).'</td><td>'.h($x['username']).'</td><td>'.h(substr($x['created_at'],0,10)).'</td><td><a class="btn btn-secondary btn-small" href="/download/report/'.h($x['id']).'">Download CSV</a></td></tr>';echo '</tbody></table></div>';}
    echo '<p class="fineprint">Reports are generated from entered records. Review their contents under applicable office procedures before relying on them.</p></section>';
    render_end($user);exit;
}

